const DEV='०१२३४५६७८९';
const toNep=s=>String(s==null?'':s).replace(/[०-९]/g,d=>DEV.indexOf(d));
const MONTHS=['बैशाख','जेठ','असार','साउन','भदौ','असोज','कात्तिक','मंसिर','पुस','माघ','फागुन','चैत'];
