const fmt=n=>(+n).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const round2=n=>Math.round(n*100)/100;
const VAT=0.13;
function parseBSDate(s){if(!s)return null;s=s.trim();let m=s.match(/^(\d{4})[-\/.:](\d{1,2})(?:[-\/.:](\d{1,2}))?$/);if(m)return{y:+m[1],m:+m[2],d:m[3]?+m[3]:null};return null;}

/* नगरपालिका/गाउँपालिकाको सांकेतिक नाम (जस्तै "KA.BA.NA.PA") लाई
   प्रिन्ट ढाँचाका लागि सानो अक्षर + अन्त्यमा थोप्लो भएको रूपमा देखाउने
   (जस्तै "ka.ba.na.pa."). थोप्लो नभएको पूरा नाम (जस्तै "SUDDODHAN") भए
   पहिलो अक्षर ठूलो बाँकी सानो अक्षरमा मात्र देखाउने । */
function formatMuniDisplay(m){
 if(!m)return'';
 if(m.indexOf('.')>=0){let s=m.toLowerCase();if(!s.endsWith('.'))s+='.';return s;}
 return m.charAt(0)+m.slice(1).toLowerCase();
}
/* Address picker factory — scoped to a root element (ids passed in) */
function wireAddress(root,ids,onChange){
 const q=id=>root.querySelector('#'+ids[id]);
 let st={muni:'',ward:'',place:'',custom:'',isCustom:false};
 const preview=()=>{
  const{muni,ward,place,custom,isCustom}=st;
  const muniDisp=formatMuniDisplay(muni);
  const munWard=ward?(muniDisp+' -'+ward):muniDisp;
  const parts=[munWard,isCustom?custom:place].filter(Boolean);
  q('preview').textContent=parts.join(', ')||'ठेगाना छान्नुहोस्...';
  q('hidden').value=parts.length?parts.join(', '):'';
  if(onChange)onChange();
 };
 const showCustom=()=>{q('customWrap').style.display='block';q('toggle').style.display='none';q('cancel').style.display='inline-block';q('custom').focus();};
 const hideCustom=()=>{q('customWrap').style.display='none';q('toggle').style.display='inline-block';q('cancel').style.display='none';q('custom').value='';st.custom='';st.isCustom=false;};
 const muniSel=q('muni');
 Object.keys(MUNI_DATA).forEach(m=>{const o=document.createElement('option');o.value=m;o.textContent=m;muniSel.appendChild(o);});
 muniSel.addEventListener('change',()=>{
  const muni=muniSel.value;st={muni,ward:'',place:'',custom:'',isCustom:false};
  const w=q('ward'),p=q('place');
  w.innerHTML='<option value="">— वडा छान्नुहोस् —</option>';p.innerHTML='<option value="">— पहिले वडा —</option>';p.disabled=true;
  if(muni&&MUNI_DATA[muni]){w.disabled=false;Object.keys(MUNI_DATA[muni]).map(Number).sort((a,b)=>a-b).forEach(x=>{const o=document.createElement('option');o.value=x;o.textContent='वडा नं. '+x;w.appendChild(o);});}else w.disabled=true;
  hideCustom();preview();
 });
 q('ward').addEventListener('change',()=>{
  const muni=muniSel.value,ward=q('ward').value;Object.assign(st,{ward,place:'',custom:'',isCustom:false});
  const p=q('place');p.innerHTML='<option value="">— टोल —</option>';
  if(muni&&ward){p.disabled=false;((MUNI_DATA[muni]&&MUNI_DATA[muni][ward])||[]).forEach(pl=>{const o=document.createElement('option');o.value=pl;o.textContent=pl;p.appendChild(o);});const oth=document.createElement('option');oth.value='__other__';oth.textContent='— अन्य (नयाँ) —';p.appendChild(oth);}else p.disabled=true;
  hideCustom();preview();
 });
 q('place').addEventListener('change',()=>{const val=q('place').value;if(val==='__other__'){st.place='';st.isCustom=true;showCustom();}else{st.place=val;st.isCustom=false;hideCustom();}preview();});
 q('custom').addEventListener('input',e=>{st.custom=e.target.value.trim();preview();});
 q('toggle').addEventListener('click',()=>{st.isCustom=true;showCustom();q('place').value='';st.place='';preview();});
 q('cancel').addEventListener('click',()=>{hideCustom();preview();});
}

/* cloneNode() ले input मा टाइप गरिएको मान (.value property) सार्दैन — केवल
   सुरुको value attribute मात्र सार्छ। त्यसैले प्रिन्ट/Word मा पठाउनुअघि हरेक
   input लाई त्यसकै हालको मान भएको सादा पाठले फेर्ने। यसो नगरे तालिकामा
   हातैले भरेको कुरा प्रिन्टमा हराउँछ। */
function bakeInputs(src,clone){
 const si=src.querySelectorAll('input,textarea'),ci=clone.querySelectorAll('input,textarea');
 for(let i=0;i<si.length&&i<ci.length;i++){
  const span=clone.ownerDocument.createElement('span');
  span.textContent=si[i].value||'';
  span.setAttribute('style','font:inherit;color:inherit');
  ci[i].replaceWith(span);
 }
 clone.querySelectorAll('select').forEach((sel,i)=>{
  const ss=src.querySelectorAll('select')[i];if(!ss)return;
  const span=clone.ownerDocument.createElement('span');
  span.textContent=ss.options[ss.selectedIndex]?ss.options[ss.selectedIndex].textContent:'';
  span.setAttribute('style','font:inherit;color:inherit');
  sel.replaceWith(span);
 });
 return clone;
}
function printEl(e){
 if(!e){window.print();return;}
 const wrap=document.createElement('div');wrap.id='nb-print-wrap';wrap.appendChild(bakeInputs(e,e.cloneNode(true)));
 document.body.appendChild(wrap);document.body.classList.add('nb-printing');
 const cleanup=()=>{document.body.classList.remove('nb-printing');wrap.remove();window.removeEventListener('afterprint',cleanup);};
 window.addEventListener('afterprint',cleanup);window.print();setTimeout(cleanup,1000);
}

/* ═══ Editable documents: "सम्पादन" (contenteditable) toggle + downloads ═══
   Shared by every printable .nb-doc across all modules. Adds an Edit toggle
   (edit inline like Word), a Word (.doc) download, and keeps the print button
   (which doubles as "Save as PDF" in the browser print dialog). */

// computed-style props copied onto the Word export so it looks the same
// (width/min-width deliberately omitted so tables reflow within the A4 page)
const DOC_STYLE_PROPS=['font-family','font-size','font-weight','font-style','color','text-align','text-decoration','text-indent','line-height','letter-spacing','background-color','border-top-width','border-top-style','border-top-color','border-right-width','border-right-style','border-right-color','border-bottom-width','border-bottom-style','border-bottom-color','border-left-width','border-left-style','border-left-color','border-collapse','padding-top','padding-right','padding-bottom','padding-left','margin-top','margin-right','margin-bottom','margin-left','vertical-align','white-space'];
function inlineStyles(src,dst){
 const cs=window.getComputedStyle(src);let s='';
 DOC_STYLE_PROPS.forEach(p=>{const v=cs.getPropertyValue(p);if(v)s+=p+':'+v+';';});
 dst.setAttribute('style',s);
 const sc=src.children,dc=dst.children;
 for(let i=0;i<sc.length&&i<dc.length;i++)inlineStyles(sc[i],dc[i]);
}
// flexbox doesn't survive Word — convert signature rows to a 100% table
function sigRowsToTables(clone){
 clone.querySelectorAll('.nb-sig-row').forEach(row=>{
  const cells=[...row.children];if(!cells.length)return;
  const tbl=document.createElement('table');tbl.setAttribute('style','width:100%;border-collapse:collapse;margin-top:48px');
  const tr=document.createElement('tr');
  cells.forEach(c=>{const td=document.createElement('td');td.setAttribute('style','text-align:center;vertical-align:top;padding:0 10px;'+(c.getAttribute('style')||''));td.innerHTML=c.innerHTML;tr.appendChild(td);});
  tbl.appendChild(tr);row.replaceWith(tbl);
 });
}
function downloadDocWord(docEl,filename){
 filename=filename||'document';
 const clone=docEl.cloneNode(true);
 inlineStyles(docEl,clone);
 bakeInputs(docEl,clone);   // टाइप गरिएको मान सादा पाठमा बदल्ने
 clone.removeAttribute('contenteditable');clone.classList.remove('nb-editing');
 clone.querySelectorAll('[contenteditable]').forEach(e=>e.removeAttribute('contenteditable'));
 /* ── Word/LibreOffice का लागि तालिका सामान्यीकरण ──────────────────
    समस्या: Word ले <colgroup>/<col> लाई प्रायः बेवास्ता गर्छ र % चौडाइ
    पनि पत्याउँदैन। <thead> लाई छुट्टै समूह ठानी अलग बक्स जसरी देखाउँछ।
    त्यसैले Word मा पठाउने प्रतिलिपिमा:
      • colgroup हटाउने
      • thead का पंक्ति tbody मै सार्ने (एउटै तालिका बन्छ)
      • हरेक कक्षलाई **पिक्सेलमा** निश्चित चौडाइ दिने (A4 मा ~655px उपलब्ध)
      • border/cellpadding HTML attribute बाट पनि दिने
    यसो गर्दा ब्राउजरको देखावटमा कुनै फरक पर्दैन — यो प्रतिलिपि मात्र हो। */
 const PAGE_W = 655;                       // A4 (margin कटाएर) अनुमानित px
 clone.querySelectorAll('table').forEach(t=>{
   t.style.borderCollapse='collapse';
   const isDoc  = t.classList.contains('nb-doc-tbl');
   const isGrid = t.classList.contains('grid') || t.classList.contains('ts-grid');
   if(!isDoc && !isGrid) return;

   t.style.width='100%'; t.setAttribute('width','100%');

   // colgroup बाट % लिएर px मा बदल्ने, अनि colgroup हटाउने
   const cg   = t.querySelector('colgroup');
   const pcts = cg ? [...cg.querySelectorAll('col')]
                      .map(c=>parseFloat(c.getAttribute('width')||c.style.width)||0) : [];
   if(cg) cg.remove();
   const pxw = pcts.map(p => Math.round(PAGE_W * p / 100));

   // thead → tbody (एउटै तालिका)
   const thead = t.querySelector('thead');
   let tbody = t.querySelector('tbody');
   if(thead){
     if(!tbody){ tbody = clone.ownerDocument.createElement('tbody'); t.appendChild(tbody); }
     [...thead.rows].reverse().forEach(r => tbody.insertBefore(r, tbody.firstChild));
     thead.remove();
   }

   if(isGrid){
     t.setAttribute('border','1'); t.setAttribute('cellspacing','0'); t.setAttribute('cellpadding','6');
   }
   t.querySelectorAll('tr').forEach(tr=>{
     [...tr.children].forEach((cell,i)=>{
       if(pxw[i]){ cell.setAttribute('width', String(pxw[i])); cell.style.width = pxw[i] + 'px'; }
       if(isGrid){
         cell.style.border = '1px solid #000';
         cell.style.verticalAlign = 'top';
         if(cell.tagName === 'TD') cell.style.height = '52px';
         else { cell.style.textAlign = 'center'; cell.style.fontWeight = '700'; }
       }
     });
   });
 });
 sigRowsToTables(clone);
 const html='<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="utf-8"><title>'+filename+'</title>'+
  '<style>@page{size:A4;margin:14mm} body{font-family:\'Noto Sans Devanagari\',sans-serif;color:#000;font-size:14px}</style></head><body>'+clone.outerHTML+'</body></html>';
 const blob=new Blob(['\ufeff',html],{type:'application/msword'});
 const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename+'.doc';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
}
// Excel export function
async function downloadDocExcel(docEl, filename) {
  filename = filename || 'document';
  if (!window.ExcelJS) {
    alert('ExcelJS library not loaded');
    return;
  }

  const Workbook = window.ExcelJS.Workbook;
  const wb = new Workbook();
  const ws = wb.addWorksheet('Report');

  // Get all tables from the document
  const tables = docEl.querySelectorAll('table.nb-doc-tbl, .grid, .ts-grid');
  
  let currentRow = 1;

  // Process each table
  tables.forEach(table => {
    // Get title if exists
    const title = table.previousElementSibling?.textContent;
    if (title && title.trim()) {
      const titleCell = ws.getCell(`A${currentRow}`);
      titleCell.value = title;
      titleCell.font = { bold: true, size: 14 };
      ws.mergeCells(`A${currentRow}:H${currentRow}`);
      currentRow++;
    }

    // Process table rows
    const rows = table.querySelectorAll('tr');
    rows.forEach(tr => {
      const cells = tr.querySelectorAll('th, td');
      cells.forEach((cell, idx) => {
        const colLetter = String.fromCharCode(65 + idx); // A, B, C, etc.
        const excelCell = ws.getCell(`${colLetter}${currentRow}`);
        
        // Get cell content
        excelCell.value = cell.textContent.trim();
        
        // Style header cells
        if (cell.tagName === 'TH') {
          excelCell.font = { bold: true };
          excelCell.alignment = { horizontal: 'center', vertical: 'center', wrapText: true };
        } else {
          excelCell.alignment = { vertical: 'center', wrapText: true };
        }
        
        // Add borders
        excelCell.border = {
          top: { style: 'thin' },
          left: { style: 'thin' },
          bottom: { style: 'thin' },
          right: { style: 'thin' }
        };
      });
      currentRow++;
    });

    currentRow++; // Empty row between tables
  });

  // Set column widths
  ws.columns.forEach(col => {
    col.width = 18;
  });

  // Generate file and download
  try {
    const buf = await wb.xlsx.writeBuffer();
    const blob = new Blob([buf], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename + '.xlsx';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1500);
  } catch (err) {
    console.error('Excel export error:', err);
    alert('Failed to export Excel file');
  }
}

// injects "सम्पादन" + "Save to Word/Excel" buttons next to an existing print button
// docType: 'excel' (default, for तालिका/गणना विवरण जस्ता table-type documents)
//          'word'  (मेमो/टिप्पणी जस्ता फारम/पत्र-type documents)
function addDocTools(root,docId,printBtnId,filename,docType,onExcel){
 docType=docType||'excel';   // 'excel' | 'word' | 'none' (सम्पादन बटन मात्र)
 const doc=root.querySelector('#'+docId),printBtn=root.querySelector('#'+printBtnId);
 if(!doc||!printBtn||printBtn.dataset.toolsAdded)return;printBtn.dataset.toolsAdded='1';
 const bar=printBtn.parentElement;
 const editBtn=document.createElement('button');editBtn.type='button';editBtn.className='sk-btn sk-bg';editBtn.textContent='Edit';
 let editing=false;
 editBtn.addEventListener('click',()=>{editing=!editing;doc.setAttribute('contenteditable',editing?'true':'false');doc.classList.toggle('nb-editing',editing);editBtn.textContent=editing?'Done':'Edit';editBtn.classList.toggle('sk-bp',editing);editBtn.classList.toggle('sk-bg',!editing);if(editing)doc.focus();});
 bar.insertBefore(editBtn,bar.firstChild);
 if(docType==='word'){
   const wordBtn=document.createElement('button');wordBtn.type='button';wordBtn.className='sk-btn sk-bg';wordBtn.textContent='Save to Word';
   wordBtn.addEventListener('click',()=>downloadDocWord(doc,filename));
   bar.insertBefore(wordBtn,printBtn);
 } else if(docType!=='none'){
   const excelBtn=document.createElement('button');excelBtn.type='button';excelBtn.className='sk-btn sk-bg';excelBtn.textContent='Save to Excel';
   // onExcel दिइएमा सोही module को \"फारामकै ढाँचा\" निर्यात चल्छ, नत्र सामान्य तालिका डम्प
   excelBtn.addEventListener('click',()=>{
    if(typeof onExcel==='function'){
     try{onExcel(doc,filename);}catch(e){alert('Excel बनाउन सकिएन : '+e.message);}
    }else downloadDocExcel(doc,filename);
   });
   bar.insertBefore(excelBtn,printBtn);
 }
}

/* ═══ हालको केसको स्वतः-सुरक्षण (localStorage) ═══
   गल्तिले ब्राउजर ब्याक/ट्याब बन्द भएमा पनि अन्तिम सम्पादन फर्किन्छ । */
function saveJSON(key,obj){try{localStorage.setItem(key,JSON.stringify(obj));}catch(e){}}
function loadJSON(key){try{const s=localStorage.getItem(key);return s?JSON.parse(s):null;}catch(e){return null;}}
